SELECT FROM gw_user u LEFT JOIN gw_dept d ON d.dept_id = u.dept_id LEFT JOIN gw_position p ON p.position_id = u.position_id LEFT JOIN gw_role r ON r.role_cd = u.role_cd WHERE u.deleted_at IS NULL AND u.use_yn = 'Y'
AND (LOWER(u.name) LIKE LOWER('%' || #{keyword} || '%') OR LOWER(u.email) LIKE LOWER('%' || #{keyword} || '%'))
AND u.dept_id = #{deptId}
ORDER BY u.name LIMIT #{limit} OFFSET #{offset}

